test-case.test:
declare variable $input-context external;
$input-context/books/book[para contains text 
("usability" ftand "studies" window 2 words) ftand "swift" distance exactly 2 words]/title

declare variable $input-context external;
let $expr := "usability studies" return
$input-context/books/book[para contains text ("usability" not in {$expr}) ftand "software" distance at most 30 words]/title

declare variable $input-context external;
$input-context/books/book[para contains text ("usability" not in
{fn:concat("usability ","studies")}) ftand "software" distance at most 30 words]/title

declare variable $input-context external;
let $expr1 := "usability studies" return
$input-context/books/book[para contains text ({fn:substring-before($expr1," ")} 
not in {$expr1}) ftand "software" distance at most 30 words]/title
